<?php require_once __DIR__.'/../includes/init.php';require_login();$page_title='Reports';$totals=$pdo->query("SELECT COUNT(*) students FROM students")->fetch();$staff=$pdo->query("SELECT COUNT(*) staff FROM staff")->fetch();$paid=$pdo->query("SELECT COALESCE(SUM(amount),0) total FROM fee_payments")->fetch();require __DIR__.'/../includes/header.php';?><h1>School Reports</h1><div class="stats"><div class="stat">Total students<div class="num"><?=$totals['students']?></div></div><div class="stat">Total staff<div class="num"><?=$staff['staff']?></div></div><div class="stat">Total fee received<div class="num"><?=number_format((float)$paid['total'],2)?></div></div></div><div class="panel"><p>These are basic summary figures. Detailed date-wise, class-wise and student-wise downloadable reports can be added after the school reporting formats are confirmed.</p></div><?php require __DIR__.'/../includes/footer.php';?>